SELECT id, row_version, created_at, updated_at, visual_beat_id, order_index
FROM shot_sequences
WHERE visual_beat_id = #{visualBeatId}

SELECT id, row_version, created_at, updated_at, visual_beat_id, order_index FROM shot_sequences WHERE visual_beat_id IN
#{id}
ORDER BY order_index ASC, id ASC

SELECT id, row_version, created_at, updated_at, visual_beat_id, order_index
FROM shot_sequences
WHERE id = #{id}
